function tableHTML(rows,cols,{selectId=null}={}){if(!rows.length)return '<div class="empty">No records found.</div>';return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${escapeHtml(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr ${selectId?`data-id="${escapeHtml(r[selectId]||'')}"`:''}>${cols.map(c=>`<td class="${c.num?'num':''}">${c.render?c.render(r):escapeHtml(r[c.key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function card(label,value,sub=''){return `<div class="card"><div class="label">${escapeHtml(label)}</div><div class="value">${escapeHtml(value)}</div>${sub?`<div class="sub">${escapeHtml(sub)}</div>`:''}</div>`}
function groupedTableHTML(rows,cols,groupBy,selectId='task_id'){if(!groupBy)return tableHTML(rows,cols,{selectId});if(!rows.length)return '<div class="empty">No records found.</div>';let last=Symbol('start'),body='';for(const r of rows){const raw=String(r[groupBy]??'');if(raw!==last){body+=`<tr class="group-row group-depth-1"><td colspan="${cols.length}"><span class="group-label">${escapeHtml(groupFieldLabel(groupBy))}</span><b>${escapeHtml(groupDisplayLabel(state.model,groupBy,r))}</b></td></tr>`;last=raw}body+=`<tr data-id="${escapeHtml(r[selectId]||'')}">${cols.map(c=>`<td class="${c.num?'num':''}">${c.render?c.render(r):escapeHtml(r[c.key]??'—')}</td>`).join('')}</tr>`}return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${escapeHtml(c.label)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`}
function activityTableHTML(rowModel,cols){if(!rowModel.length)return '<div class="empty">No records found.</div>';const body=rowModel.map(row=>{if(row.kind==='activity'){const r=row.task;return `<tr data-id="${escapeHtml(r.task_id||'')}" data-row-key="${escapeHtml(row.key)}">${cols.map(c=>`<td class="${c.num?'num':''}">${c.render?c.render(r):escapeHtml(r[c.key]??'—')}</td>`).join('')}</tr>`}const depth=Math.max(0,Number(row.depth)||0),label=row.kind==='wbs'?(row.code?`${row.code} — ${row.label}`:row.label):(row.label||row.value||'Group'),toggle=row.kind==='wbs'&&row.wbsId!==''?`<button class="activity-wbs-toggle" data-activity-wbs-toggle="${escapeHtml(row.wbsId)}" title="Expand / collapse WBS">${row.hasChildren||row.directCount?(row.expanded?'▾':'▸'):'·'}</button>`:'<span class="activity-wbs-toggle-spacer"></span>';return `<tr class="group-row ${row.kind==='wbs'?'wbs-band':''}" data-row-key="${escapeHtml(row.key||'')}" style="--group-depth:${depth}"><td colspan="${cols.length}"><div class="activity-group-label" style="padding-left:${depth*16}px">${toggle}<span>${escapeHtml(label)}</span><small>${row.count??''}${row.count===1?' activity':' activities'}</small></div></td></tr>`}).join('');return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${escapeHtml(c.label)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`}
