 const cols=colKeys.map(key=>({key,label:labels[key]||key,num:/drtn|float|pct|qty|cost/i.test(key),render:r=>{if(key==='wbs_id')return escapeHtml(wbsDisplayLabel(state.model,r.wbs_id));if(key==='clndr_id')return escapeHtml(calendarDisplayLabel(state.model,r.clndr_id));if(['early_start_date','target_start_date'].includes(key)){const d=editableActivityDates(r);return `<input class="activity-inline-edit date" data-inline-field="start" data-task-id="${escapeHtml(r.task_id)}" type="datetime-local" value="${escapeHtml(datetimeLocalValue(d.start))}" title="Planning input. Press F9 to recalculate logic.">`}if(['early_end_date','target_end_date'].includes(key)){const d=editableActivityDates(r);return `<input class="activity-inline-edit date" data-inline-field="finish" data-task-id="${escapeHtml(r.task_id)}" type="datetime-local" value="${escapeHtml(datetimeLocalValue(d.finish))}" title="Planning input. Press F9 to recalculate logic.">`}if(key==='phys_complete_pct')return `<input class="activity-inline-edit pct" data-inline-field="percent" data-task-id="${escapeHtml(r.task_id)}" type="number" min="0" max="100" step="0.1" value="${escapeHtml(r[key]??0)}">`;if(/date/.test(key))return fmtDate(r[key]);return escapeHtml(r[key]??'—')}}));
 if(pbl)cols.push({key:'blFinish',label:'BL Finish',render:r=>fmtDate(pblById.get(String(r.task_id))?.baseline_finish)},{key:'finishVar',label:'Finish Var',render:r=>{const v=pblById.get(String(r.task_id))?.finish_variance_days;return Number.isFinite(v)?`<span class="${v>0?'baseline-late':v<0?'baseline-ahead':''}">${v>0?'+':''}${v.toFixed(1)}d</span>`:'—'}});
 const statusOptions=[...new Set(taskRows(state.model,state.projId).map(t=>t.status_code).filter(Boolean))];
 $('#view').innerHTML=`<div class="p6-activity-workspace"><div class="p6-layout-strip"><div class="p6-layout-left"><label>Layout: <select id="activityLayout">${state.layouts.map(x=>`<option value="${escapeHtml(x.id)}" ${x.id===state.activeLayoutId?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Filter: <select id="activityStatus"><option value="">All Activities</option>${statusOptions.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('')}</select></label><button id="columnsBtn">Columns…</button><button id="groupSortBtn">Group & Sort…</button>${state.needsRecalc?'<span class="activity-f9-warning">Planning inputs changed — press F9</span>':''}</div><div class="p6-layout-right"><span>${visibleTasks.length.toLocaleString()} activities</span><button id="showBaselineToggle">${state.showBaselineBars?'Hide':'Show'} Baseline</button><button id="zoomOutBtn">−</button><button id="zoomInBtn">+</button></div></div><div class="p6-activity-main" id="activityMain"><div id="activityTable" class="p6-grid-pane">${activityTableHTML(rowModel,cols)}</div><div id="activitySplitter" class="p6-splitter" title="Drag to resize table / Gantt"></div><div id="activityGantt" class="gantt p6-gantt-pane"></div></div><div class="p6-detail-pane" id="detailPanel"></div></div>`;
 bindActivityRows();bindActivityInlineEditors();$$('[data-activity-wbs-toggle]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.activityWbsToggle;state.activityWbsExpanded[id]=state.activityWbsExpanded[id]===false?true:false;renderActivities()});
