function relationshipMini(a){const row=(r,pred)=>{const id=pred?r.pred_task_id:r.task_id,t=state.model.find('TASK','task_id',id);return `<tr data-id="${escapeHtml(id)}"><td>${escapeHtml(t?.task_code||id)}</td><td>${escapeHtml(t?.task_name||'')}</td><td>${escapeHtml(relationshipTypeLabel(r.pred_type))}</td><td class="num">${escapeHtml(r.lag_hr_cnt||0)}</td></tr>`};return `<h4>Predecessors</h4><table><thead><tr><th>ID</th><th>Name</th><th>Type</th><th>Lag h</th></tr></thead><tbody>${a.preds.map(r=>row(r,true)).join('')||'<tr><td colspan="4">None</td></tr>'}</tbody></table><h4>Successors</h4><table><thead><tr><th>ID</th><th>Name</th><th>Type</th><th>Lag h</th></tr></thead><tbody>${a.succs.map(r=>row(r,false)).join('')||'<tr><td colspan="4">None</td></tr>'}</tbody></table>`}
