function calendarWeekEditor(def){const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];return `<div class="calendar-week-editor">${days.map(d=>{const periods=def.week[d]||[],text=periods.map(p=>`${p.start}-${p.finish}`).join(', ');return `<div class="calendar-week-row"><b>${d}</b><label><input type="checkbox" data-cal-working="${d}" ${periods.length?'checked':''}> Working</label><input data-cal-periods="${d}" value="${escapeHtml(text)}" placeholder="08:00-12:00, 13:00-17:00"></div>`}).join('')}</div>`}
function projectCalendarHTML(def,range){
 const start=new Date(range.start.getFullYear(),range.start.getMonth(),1),finish=new Date(range.finish.getFullYear(),range.finish.getMonth()+1,0),months=[];let c=new Date(start);let guard=0;while(c<=finish&&guard++<240){const y=c.getFullYear(),m=c.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),lead=first.getDay(),cells=[];for(let i=0;i<lead;i++)cells.push('<span class="calendar-date blank"></span>');for(let d=1;d<=last.getDate();d++){const date=new Date(y,m,d),s=calendarDayStatus(def,date),cls=s.exception?(s.working?'exception-working':'exception-off'):(s.working?'working':'off'),title=s.periods?.map(p=>`${p.start}-${p.finish}`).join(', ')||'Non-working';cells.push(`<button class="calendar-date ${cls}" data-cal-date="${s.key}" title="${escapeHtml(title)}"><b>${d}</b>${s.exception?'<i>E</i>':''}</button>`)}months.push(`<section class="calendar-month"><h4>${first.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h4><div class="calendar-dow">${['S','M','T','W','T','F','S'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-date-grid">${cells.join('')}</div></section>`);c=new Date(y,m+1,1)}return `<div class="calendar-project-scroll">${months.join('')}</div>`;
}
function periodsFromText(text){return String(text||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>{const [start,finish]=x.split('-').map(v=>v.trim());if(!start||!finish)throw new Error(`Invalid work period: ${x}`);return {start,finish}})}
