function saveProjectPackage(){if(!state.model)return;downloadText(`${baseName()}.ussproj`,serializeProjectPackage(projectPackage()),'application/json;charset=utf-8');toast('Project package downloaded')}
async function openProjectPackage(file){try{const pkg=parseProjectPackage(await file.text());state.model=modelFromPackage(pkg);state.sourceFormat=state.model.sourceFormat;state.settings={...state.settings,...(pkg.settings||{})};state.baselines=(pkg.baselines||[]).map(b=>{if(b.model)return b;const bm=new XERModel({header:[],tables:new Map((b.tables||[]).map(([n,t])=>[n,{name:t.name||n,fields:[...(t.fields||[])],rows:(t.rows||[]).map(r=>({...r}))}])),warnings:[],sourceText:''});bm.sourceFormat=b.format||'xer';return {...b,model:bm}});state.primaryBaselineId=state.baselines.find(b=>b.role==='Primary')?.id||null;state.selectedBaselineId=state.primaryBaselineId||state.baselines[0]?.id||null;state.bimModels=pkg.bimModels||[];state.layouts=pkg.layouts?.length?pkg.layouts:[defaultLayout()];state.scenarios=pkg.scenarios||[];state.projId=state.model.table('PROJECT')[0]?.proj_id||state.model.table('TASK')[0]?.proj_id||null;state.revisionRepository=pkg.revisions?.length?pkg.revisions:[createRevision(state.model,{name:'Package opened',projectId:state.projId})];state.selectedRevisionA=state.revisionRepository[0]?.id||'';state.selectedRevisionB=state.revisionRepository.at(-1)?.id||'';state.audit=new AuditLog();state.audit.items=pkg.audit||[];state.history=new EditHistory(state.model);state.fileName=file.name;state.selectedTaskId=state.model.table('TASK')[0]?.task_id||null;state.selectedWbsId=wbsRows(state.model,state.projId)[0]?.wbs_id||null;state.revisionSnapshots=[snapshotModel(state.model,'Package opened')];state.dirty=false;populateProjects();updateEditButtons();render();toast('Project package opened')}catch(e){alert(`Could not open project package: ${e.message}`)}}
function exportCurrent(){if(!state.model)return;let rows=[],name=state.view;switch(state.view){case'activities':rows=filterTasks();break;case'relationships':rows=predRows(state.model,state.projId);break;case'resources':rows=summarizeResources(state.model,state.projId);break;case'resourceSheet':rows=resourceSheetRows(state.model,state.projId);name='resource-sheet';break;case'resourceProfiles':rows=buildResourceTimeSeries(state.model,state.projId,profileFilters());name='resource-profile';break;case'analysis':rows=analyzeSchedule(state.model,state.projId,state.settings).issues;break;case'intelligence':rows=state.forensicComparison?.changes||[];name='material-change-register';break;case'health':rows=enhancedScheduleHealth(state.model,state.projId,state.settings).dcma.issues||[];name='schedule-health';break;case'trends':rows=activityTimeline(state.revisionRepository,state.selectedTrendTask||taskRows(state.model,state.projId)[0]?.task_code||'');name='schedule-time-machine';break;case'reporting':rows=buildLookahead(state.model,state.projId,{weeks:Number(state.settings.lookaheadWeeks||6)});name='lookahead';break;case'searchAll':rows=globalScheduleSearch(state.model,state.search,{limit:5000});name='global-search';break;case'baselines':{const b=selectedBaseline();rows=b?baselineRows(state.model,state.projId,b,state.settings.hoursPerDay):[];name='baseline-variance';break}case'compare':rows=state.compareModel?compareModels(state.compareModel,state.model,state.compareProjId,state.projId).changes:[];break;case'raw':rows=state.model.table(state.rawTable||'TASK');name=state.rawTable||'TASK';break;default:rows=taskRows(state.model,state.projId)}if(!rows.length)return toast('Nothing to export in this view');downloadText(`${name}.csv`,toCSV(rows),'text/csv;charset=utf-8');}

function nextActivityCode(){const used=new Set(taskRows(state.model,state.projId).map(t=>String(t.task_code||'').toUpperCase()));let n=1,code='NEW-001';while(used.has(code)){n++;code=`NEW-${String(n).padStart(3,'0')}`}return code}
function addActivityFromToolbar(){if(!state.model)return;try{const current=state.model.find('TASK','task_id',state.selectedTaskId)||taskRows(state.model,state.projId)[0];checkpoint('Add activity');const t=addTask(state.model,state.projId,{wbs_id:current?.wbs_id||wbsRows(state.model,state.projId)[0]?.wbs_id||'',clndr_id:current?.clndr_id||state.model.table('CALENDAR')[0]?.clndr_id||'',task_code:nextActivityCode(),task_name:'New Activity'});state.selectedTaskId=t.task_id;markDirty();setView('activities');toast(`Added ${t.task_code}`)}catch(e){alert(`Could not add activity: ${e.message}`)}}
function deleteActivityFromToolbar(){if(!state.model||!state.selectedTaskId)return;const t=state.model.find('TASK','task_id',state.selectedTaskId);if(!t)return;if(!confirm(`Delete ${t.task_code||t.task_id} — ${t.task_name||''}?\n\nDependent relationships, assignments, codes and activity UDF values will also be removed.`))return;try{checkpoint('Delete activity');deleteTask(state.model,state.selectedTaskId);state.selectedTaskId=taskRows(state.model,state.projId)[0]?.task_id||null;markDirty();setView('activities');toast('Activity deleted')}catch(e){alert(`Could not delete activity: ${e.message}`)}}
function levelResourcesNow(){if(!state.model)return;const prior=state.settings.resourceLevelingEnabled;state.settings.resourceLevelingEnabled=true;persistSettings();toast('Resource leveling enabled — calculating schedule');try{runSchedule()}finally{state.settings.resourceLevelingEnabled=prior;persistSettings()}}
function dispatchMenuCommand(command){executeCommand(command)}

// Open controls are native <label for="fileInput"> elements.  The label's
// default browser action opens the chooser directly; no JavaScript click
// indirection is required for mouse/touch use.
for(const control of [$('#welcomeOpen'),$('#openBtn'),$('#menuOpenSchedule')].filter(Boolean)){
 control.addEventListener('keydown',event=>{
   if(event.key==='Enter'||event.key===' '){event.preventDefault();openScheduleFromDevice();}
 });
}
$('#fileInput').addEventListener('change',async event=>{
 const input=event.currentTarget;
 const file=input.files?.[0]||null;
 // Clear after taking the File reference so re-selecting the same path emits
 // another change event on all major browsers.
 input.value='';
 closeP6Menus();
 if(file)await loadFile(file,false);
});
$('#projectFolderInput').onchange=async e=>{
 const files=[...(e.target.files||[])];e.target.value='';if(!files.length)return;
 try{state.projectFolderHandle=createSessionProjectFolder(files);state.projectFolderTree=null;state.projectFolderExpanded={__root__:true};state.projectFolderPersistence='session';if(state.view!=='eps')setView('eps');else renderEPS();toast('Local Projects folder linked for this browser session — files stay on this device');}
 catch(err){alert(`Could not open project folder: ${err.message}`)}
};
$('#compareInput').onchange=e=>e.target.files[0]&&loadFile(e.target.files[0],true);
$('#baselineInput').onchange=e=>e.target.files.length&&loadBaselines([...e.target.files]);
$('#packageInput').onchange=e=>e.target.files[0]&&openProjectPackage(e.target.files[0]);
$('#projectSelect').onchange=e=>{state.projId=e.target.value;state.selectedTaskId=taskRows(state.model,state.projId)[0]?.task_id||null;state.selectedWbsId=wbsRows(state.model,state.projId)[0]?.wbs_id||null;state.lastCalculationDiscrepancies=[];render();updateEditButtons()};
$('#nav').onclick=e=>{const b=e.target.closest('button[data-view]'),table=e.target.closest('button[data-table]');if(b)setView(b.dataset.view);if(table){state.rawTable=table.dataset.table;setView('raw');$('#viewTitle').textContent=table.dataset.label||table.dataset.table}};
function p6TopMenus(){return $$('#menuBar > details')}
function closeP6Menus(except=null){closeMenus(p6TopMenus(),except)}
function toggleP6Menu(menu){return toggleExclusiveMenu(p6TopMenus(),menu)}
for(const menu of p6TopMenus())setMenuOpen(menu,menu.hasAttribute('open'));
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#menuBar'))closeP6Menus()},true);
$('#menuBar').onclick=e=>{
 const summary=e.target.closest('summary');
 if(summary&&summary.closest('#menuBar')===$('#menuBar')){
  e.preventDefault();
  e.stopPropagation();
  toggleP6Menu(summary.parentElement);
  return;
 }
 const view=e.target.closest('button[data-view]'),table=e.target.closest('button[data-table]'),cmd=e.target.closest('button[data-command]');
 if(view){closeP6Menus();setView(view.dataset.view);return}
 if(table){closeP6Menus();state.rawTable=table.dataset.table;setView('raw');$('#viewTitle').textContent=table.dataset.label||table.dataset.table;return}
 if(cmd){closeP6Menus();executeCommand(cmd.dataset.command);return}
};
$('#p6Toolbar').onclick=e=>{const cmd=e.target.closest('button[data-command]');if(cmd&&!cmd.disabled)executeCommand(cmd.dataset.command)};
$('#globalSearch').oninput=e=>{state.search=e.target.value;if(state.model&&state.view==='activities')renderActivities()};
$('#exportBtn').onclick=exportCurrent;
$('#savePackageBtn').onclick=saveProjectPackage;$('#openPackageBtn').onclick=()=>$('#packageInput').click();
$('#themeBtn').onclick=()=>document.documentElement.classList.toggle('dark');
$('#ganttZoom').onchange=e=>{state.ganttZoom=Number(e.target.value)||1;if(state.view==='activities')renderActivities()};
window.addEventListener('keydown',e=>{
 const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'');
 if(e.key==='Escape'){for(const d of $$('#menuBar details[open]'))d.removeAttribute('open');if($('#modal')?.open)$('#modal').close();return}
 if(state.view==='wbs'&&!typing&&state.model){
   if(e.key==='Insert'){e.preventDefault();const parent=state.selectedWbsId||'';checkpoint('Add child WBS');const w=addWBS(state.model,state.projId,parent,{wbs_name:'New WBS'});state.selectedWbsId=w.wbs_id;renderWBS();toast('WBS added');return}
   if(e.key==='Delete'&&state.selectedWbsId){e.preventDefault();showWBSDeleteDialog(state.model.find('PROJWBS','wbs_id',state.selectedWbsId));return}
   if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='c'&&state.selectedWbsId){e.preventDefault();state.wbsClipboard=state.selectedWbsId;toast('WBS branch copied');return}
   if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='v'&&state.wbsClipboard&&state.selectedWbsId){e.preventDefault();try{checkpoint('Paste WBS branch');const r=cloneWBSBranch(state.model,state.wbsClipboard,{newParentWbsId:state.selectedWbsId,includeActivities:true});state.selectedWbsId=r.rootWbsId;renderWBS();toast('WBS branch pasted')}catch(err){state.history?.undo();alert(err.message)}return}
 }
 if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='z'&&!typing){e.preventDefault();doRedo();return}
 const cmd=commandForKeyboardEvent(e);
 if(cmd&&(!typing||['schedule','save','find','print','open'].includes(cmd.id))){e.preventDefault();executeCommand(cmd.id)}
});
window.addEventListener('beforeunload',e=>{if(!state.dirty)return;e.preventDefault();e.returnValue=''});
window.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('dragging')});window.addEventListener('dragleave',e=>{if(e.clientX===0&&e.clientY===0)document.body.classList.remove('dragging')});window.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('dragging');const f=[...e.dataTransfer.files].find(f=>/\.(xer|xml)$/i.test(f.name));if(f)loadFile(f);else toast('Drop a .xer or .xml schedule file')});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));

// Developer/demo harness: append ?demo=1 to load the bundled sample XER automatically.
if(new URLSearchParams(location.search).get('demo')==='1'){
  fetch('./sample/sample-project.xer').then(r=>r.text()).then(text=>loadFile(new File([text],'sample-project.xer',{type:'text/plain'}))).catch(e=>console.error('Demo load failed',e));
}
